<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();$uploadDir=__DIR__.'/../uploads';$web='/uploads/';if(!is_dir($uploadDir))@mkdir($uploadDir,0755,true);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_FILES['file'])&&$_FILES['file']['error']===UPLOAD_ERR_OK){$f=$_FILES['file'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(isset($allowed[$mime])&&$f['size']<=5*1024*1024){$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(move_uploaded_file($f['tmp_name'],$uploadDir.'/'.$name)){$pdo->prepare('INSERT INTO media(path,mime,size_bytes) VALUES(?,?,?)')->execute([$web.$name,$mime,(int)$f['size']]);flash('Image ajoutée');}else flash('Échec de déplacement','error');}else flash('Format ou taille invalide','error');}redirect_self();}$media=[];try{$media=$pdo->query('SELECT * FROM media ORDER BY id DESC LIMIT 200')->fetchAll();}catch(Throwable $e){}admin_layout_start('Médias');echo '<form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="file" name="file" accept="image/*" required><button>Importer</button></form><table><tr><th>Image</th><th>Chemin</th><th>MIME</th><th>Taille</th><th>Date</th></tr>';foreach($media as $m)echo '<tr><td><img src="'.h($m['path']).'" style="max-width:100px;max-height:70px"></td><td>'.h($m['path']).'</td><td>'.h($m['mime']).'</td><td>'.h($m['size_bytes']).' octets</td><td>'.h($m['created_at']).'</td></tr>';echo '</table>';admin_layout_end();